# ---- state ------------------------------------------------------------------------------
save() {  # save KEY VALUE: remember a value so `resume` can pick up from here
  printf -v "$1" '%s' "$2"
  printf '%s=%q\n' "$1" "$2" >>"$RUN_DIR/state.env"
}

install_helpers() {
  PY="$RUN_DIR/py"
  mkdir -p "$PY"
  echo "$CONSOLE_CHANNEL_GZ_B64" | base64 -d | gunzip >"$PY/console_channel.py"
  echo "$NOTICE_TIMING_GZ_B64" | base64 -d | gunzip >"$PY/notice_timing.py"
}

instance_state() {
  aws ec2 describe-instances --instance-ids "$IID" \
    --query 'Reservations[0].Instances[0].State.Name' --output text 2>/dev/null || echo unknown
}

# ---- console ----------------------------------------------------------------------------
snapshot() {  # merge the newest console window into console.txt
  local mode="${1:---latest}" merged
  if [ "$mode" = --latest ]; then
    aws ec2 get-console-output --instance-id "$IID" --latest --query Output --output text \
      >"$RUN_DIR/snapshot.txt" 2>/dev/null || return 0
  else
    aws ec2 get-console-output --instance-id "$IID" --query Output --output text \
      >"$RUN_DIR/snapshot.txt" 2>/dev/null || return 0
  fi
  [ "$(cat "$RUN_DIR/snapshot.txt")" = None ] && return 0
  merged="$(python3 "$PY/console_channel.py" merge "$RUN_DIR/console.txt" "$RUN_DIR/snapshot.txt" \
    --cli-text)"
  case "$merged" in
    *'"gap": true'*) say "warning: some console output was missed between polls" ;;
  esac
}

print_events() {  # show instance progress and spot signals not shown yet
  python3 - "$RUN_DIR/console.txt" "$RUN_DIR/events.seen" <<'PY'
import json, sys
from pathlib import Path
console, seen_file = Path(sys.argv[1]), Path(sys.argv[2])
if not console.exists():
    sys.exit(0)
events = []
for line in console.read_text(errors="replace").splitlines():
    at = line.find("KVEVAC {")
    if at < 0:
        continue
    try:
        event = json.loads(line[at + 7:])
    except ValueError:
        continue
    if event.get("event") != "heartbeat" and event not in events:  # skip re-sent copies
        events.append(event)
seen = int(seen_file.read_text()) if seen_file.exists() else 0
for event in events[seen:]:
    if event["event"] == "job":
        print(f"  instance | {event.get('stage')}: {event.get('msg')}")
    else:
        detail = event.get("body") or event.get("error") or ""
        print(f"  instance | {event['event']} {json.dumps(detail) if detail else ''}")
seen_file.write_text(str(len(events)))
PY
}

# ---- AWS setup --------------------------------------------------------------------------
ensure_role() {
  ROLE_ARN="$(aws iam get-role --role-name "$FIS_ROLE" --query Role.Arn --output text 2>/dev/null)" \
    && return 0
  say "creating IAM role $FIS_ROLE for AWS FIS (one time; it stays and costs nothing)"
  echo "$FIS_TRUST_JSON" >"$RUN_DIR/fis-trust.json"
  ROLE_ARN="$(aws iam create-role --role-name "$FIS_ROLE" \
    --assume-role-policy-document "file://$RUN_DIR/fis-trust.json" \
    --tags "Key=project,Value=$TAG" --query Role.Arn --output text)"
  aws iam attach-role-policy --role-name "$FIS_ROLE" \
    --policy-arn arn:aws:iam::aws:policy/service-role/AWSFaultInjectionSimulatorEC2Access
}

make_user_data() {
  local size
  {
    echo '#!/bin/bash'
    echo "export KVEVAC_MAX_MIN=$MAX_MIN"
    for name in $PASS_THROUGH; do
      if [ -n "${!name:-}" ]; then printf 'export %s=%q\n' "$name" "${!name}"; fi
    done
    if [ "${KVEVAC_JOB:-calibrate}" = phase3 ]; then
      echo "$USERDATA_PHASE3_GZ_B64" | base64 -d | gunzip
    else
      echo "$USERDATA_GZ_B64" | base64 -d | gunzip
    fi
  } | gzip -9n >"$RUN_DIR/user-data.gz"
  size="$(wc -c <"$RUN_DIR/user-data.gz")"
  [ "$size" -lt 16384 ] || die "user-data is $size bytes; EC2 allows 16384"
}

candidate_subnets() {  # lines "price az subnet", cheapest first, zones offering the type
  local offered prices
  offered="$(aws ec2 describe-instance-type-offerings --location-type availability-zone \
    --filters "Name=instance-type,Values=$INSTANCE_TYPE" \
    --query 'InstanceTypeOfferings[].Location' --output text)"
  prices="$(aws ec2 describe-spot-price-history --instance-types "$INSTANCE_TYPE" \
    --product-descriptions Linux/UNIX --start-time "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    --query 'SpotPriceHistory[].[AvailabilityZone,SpotPrice]' --output text)"
  if [ -n "${SUBNET_ID:-}" ]; then
    aws ec2 describe-subnets --subnet-ids "$SUBNET_ID" \
      --query 'Subnets[].[AvailabilityZone,SubnetId]' --output text
  else
    aws ec2 describe-subnets --filters Name=default-for-az,Values=true \
      --query 'Subnets[].[AvailabilityZone,SubnetId]' --output text
  fi | while read -r az subnet; do
    [ -n "${SUBNET_ID:-}" ] || [[ " $(echo $offered) " == *" $az "* ]] || continue
    price="$(echo "$prices" | awk -v az="$az" '$1 == az {print $2; exit}')"
    echo "${price:-9.99} $az $subnet"
  done | sort -n
}

try_zones() {  # try_zones AMI ROOTDEV CANDIDATES: one pass over the zones; 0 if launched
  local ami="$1" rootdev="$2" candidates="$3" err market=() price
  if [ "$MARKET" = spot ]; then
    market=(--instance-market-options '{"MarketType":"spot","SpotOptions":{"SpotInstanceType":"one-time","InstanceInterruptionBehavior":"terminate"}}')
  fi
  while read -r price az subnet; do
    [ "$MARKET" = spot ] || price="$ON_DEMAND_PRICE"
    say "requesting $([ "$MARKET" = spot ] && echo a || echo an) $MARKET $INSTANCE_TYPE in $az (\$$price/h)"
    if IID="$(aws ec2 run-instances --instance-type "$INSTANCE_TYPE" --image-id "$ami" \
        --subnet-id "$subnet" --count 1 ${market[@]+"${market[@]}"} \
        --instance-initiated-shutdown-behavior terminate \
        --metadata-options HttpTokens=required,HttpEndpoint=enabled \
        --block-device-mappings "[{\"DeviceName\":\"$rootdev\",\"Ebs\":{\"VolumeSize\":$ROOT_GB,\"VolumeType\":\"gp3\",\"DeleteOnTermination\":true}}]" \
        --user-data "fileb://$RUN_DIR/user-data.gz" \
        --tag-specifications "ResourceType=instance,Tags=[{Key=project,Value=$TAG},{Key=Name,Value=kvevac-$STAMP}]" \
          "ResourceType=volume,Tags=[{Key=project,Value=$TAG}]" \
        --query 'Instances[0].InstanceId' --output text 2>"$RUN_DIR/launch.err")"; then
      save IID "$IID"; save AZ "$az"; save SPOT_PRICE "$price"; save LAUNCHED_AT "$(now)"
      save MARKET "$MARKET"
      return 0
    fi
    IID=""
    err="$(cat "$RUN_DIR/launch.err")"
    case "$err" in
      *InsufficientInstanceCapacity*|*capacity-not-available*|*SpotMaxPriceTooLow*|*Unsupported*)
        say "no $MARKET capacity in $az; trying the next zone" ;;
      *MaxSpotInstanceCountExceeded*|*VcpuLimitExceeded*)
        die "$MARKET vCPU quota too low for $INSTANCE_TYPE: $err" ;;
      *) die "run-instances failed: $err" ;;
    esac
  done <<<"$candidates"
  return 1
}

launch() {
  local candidates rootdev snapshot_gb ami
  ACCOUNT="$(aws sts get-caller-identity --query Account --output text)" \
    || die "the AWS CLI has no working credentials (run this in AWS CloudShell)"
  save ACCOUNT "$ACCOUNT"
  local leftover
  leftover="$(aws ec2 describe-instances \
    --filters "Name=tag:project,Values=$TAG" Name=instance-state-name,Values=pending,running \
    --query 'Reservations[].Instances[].InstanceId' --output text)"
  [ -z "$leftover" ] || [ "$leftover" = None ] \
    || die "instances from an earlier run are still up ($leftover). Run: bash $0 cleanup"
  ensure_role
  save ROLE_ARN "$ROLE_ARN"
  ami="$(aws ssm get-parameter --name "$AMI_PARAM" --query Parameter.Value --output text)"
  read -r rootdev snapshot_gb <<<"$(aws ec2 describe-images --image-ids "$ami" \
    --query 'Images[0].[RootDeviceName,BlockDeviceMappings[0].Ebs.VolumeSize]' --output text)"
  # The root volume cannot be smaller than the AMI's snapshot.
  if [[ "$snapshot_gb" =~ ^[0-9]+$ ]] && [ "$snapshot_gb" -gt "$ROOT_GB" ]; then
    ROOT_GB=$((snapshot_gb + 50))
  fi
  say "AMI $ami (Deep Learning Base OSS Nvidia, Ubuntu 22.04), root volume ${ROOT_GB} GB"
  make_user_data
  candidates="$(candidate_subnets)"
  [ -n "$candidates" ] || die "no default-VPC subnet in a zone that offers $INSTANCE_TYPE; set SUBNET_ID"
  local give_up=$(($(now) + RETRY_MIN * 60))
  while :; do
    try_zones "$ami" "$rootdev" "$candidates" && break
    if [ "$(now)" -ge "$give_up" ]; then
      die "no zone had $MARKET capacity for $INSTANCE_TYPE; try again later (or RETRY_MIN=120)"
    fi
    say "no $MARKET capacity anywhere; retrying in ${RETRY_EVERY_S}s" \
      "(until $(date -u -r "$give_up" +%H:%M:%S 2>/dev/null || date -u -d "@$give_up" +%H:%M:%S) UTC)"
    sleep "$RETRY_EVERY_S"
  done
  say "launched $IID; waiting for it to start"
  aws ec2 wait instance-running --instance-ids "$IID"
}

# ---- phases -----------------------------------------------------------------------------
collect_results() {
  local deadline=$((LAUNCHED_AT + (MAX_MIN - 3) * 60)) state
  say "following the instance console every ${POLL_S}s (install + model download + measurements: about 25-40 min)"
  while :; do
    snapshot
    print_events
    if python3 "$PY/console_channel.py" decode "$RUN_DIR/console.txt" \
        --out "$RUN_DIR/results.tgz" >"$RUN_DIR/decode.json" 2>/dev/null; then
      mkdir -p "$RUN_DIR/results"
      tar -xzf "$RUN_DIR/results.tgz" -C "$RUN_DIR" \
        && save RESULTS_OK 1 && say "results received and checksum-verified" && return 0
    fi
    state="$(instance_state)"
    case "$state" in
      shutting-down|terminated|stopping|stopped)
        say "the instance is $state before the results arrived (spot reclaim or the spending cap)"
        return 1 ;;
    esac
    if [ "$(now)" -ge "$deadline" ]; then
      say "gave up waiting for results ($(cat "$RUN_DIR/decode.json" 2>/dev/null))"
      return 1
    fi
    sleep "$POLL_S"
  done
}

interrupt() {
  echo "$FIS_TEMPLATE_JSON" >"$RUN_DIR/fis-base.json"
  python3 - "$RUN_DIR/fis-base.json" "$RUN_DIR/fis.json" \
    "arn:aws:ec2:$REGION:$ACCOUNT:instance/$IID" "$ROLE_ARN" "$TAG" <<'PY'
import json, sys
base, out, arn, role, tag = sys.argv[1:6]
template = json.load(open(base))
# Target exactly this instance rather than "any instance with the tag".
template["targets"] = {"kvevacSpot": {"resourceType": "aws:ec2:spot-instance",
                                      "resourceArns": [arn], "selectionMode": "ALL"}}
template["roleArn"] = role
template["tags"] = {"project": tag}
json.dump(template, open(out, "w"), indent=1)
PY
  local id="" try template
  template="$(aws fis create-experiment-template --cli-input-json "file://$RUN_DIR/fis.json" \
    --query experimentTemplate.id --output text)" \
    || { say "could not create the FIS experiment template; skipping notice timing"; return 1; }
  save TEMPLATE_ID "$template"
  for try in 1 2 3 4 5 6; do  # a just-created IAM role takes a few seconds to be usable
    id="$(aws fis start-experiment --experiment-template-id "$TEMPLATE_ID" \
      --tags "project=$TAG" --query experiment.id --output text 2>"$RUN_DIR/fis.err")" && break
    say "FIS not ready yet (try $try): $(head -c 200 "$RUN_DIR/fis.err")"
    id=""
    sleep 10
  done
  [ -n "$id" ] || { say "could not start the FIS experiment; skipping notice timing"; return 1; }
  save EXPERIMENT_ID "$id"
  save FIS_STARTED_AT "$(now)"
  say "FIS experiment $id started: 2-minute spot interruption notice on $IID"
}

follow_notice() {
  local end=$(($(now) + NOTICE_WAIT_S)) state
  while [ "$(now)" -lt "$end" ]; do
    snapshot
    print_events
    state="$(instance_state)"
    [ "$state" = terminated ] && break
    sleep 5
  done
  snapshot
  snapshot buffered  # the output EC2 stores after termination
  print_events
  save EXPERIMENT_STATE "$(aws fis get-experiment --id "$EXPERIMENT_ID" \
    --query experiment.state.status --output text 2>/dev/null || echo unknown)"
}

analyze() {
  if python3 "$PY/notice_timing.py" "$RUN_DIR/console.txt" >"$RUN_DIR/notice.json" 2>/dev/null; then
    say "notice timing written to notice.json"
  else
    rm -f "$RUN_DIR/notice.json"
    say "no interruption notice in the console log, so no notice timing this run"
  fi
}

cleanup_run() {
  [ -n "${IID:-}" ] || return 0
  local state
  state="$(instance_state)"
  if [ "$state" != terminated ]; then
    say "terminating $IID ($state)"
    aws ec2 terminate-instances --instance-ids "$IID" >/dev/null || true
  fi
  aws ec2 wait instance-terminated --instance-ids "$IID" 2>/dev/null \
    || say "WARNING: $IID is not confirmed terminated; check the EC2 console"
  if [ -n "${TEMPLATE_ID:-}" ]; then
    aws fis delete-experiment-template --id "$TEMPLATE_ID" >/dev/null 2>&1 || true
  fi
  save ENDED_AT "$(now)"
}

cleanup_all() {
  local ids templates
  ids="$(aws ec2 describe-instances --filters "Name=tag:project,Values=$TAG" \
    Name=instance-state-name,Values=pending,running,stopping,stopped \
    --query 'Reservations[].Instances[].InstanceId' --output text)"
  if [ -n "$ids" ] && [ "$ids" != None ]; then
    say "terminating $ids"
    # shellcheck disable=SC2086
    aws ec2 terminate-instances --instance-ids $ids >/dev/null
    # shellcheck disable=SC2086
    aws ec2 wait instance-terminated --instance-ids $ids
  fi
  templates="$(aws fis list-experiment-templates \
    --query "experimentTemplates[?tags.project=='$TAG'].id" --output text)"
  for t in $templates; do
    [ "$t" = None ] || aws fis delete-experiment-template --id "$t" >/dev/null
  done
  say "nothing tagged project=$TAG is left running"
}

summary() {
  python3 - "$RUN_DIR" <<'PY' || true
import json, sys
from pathlib import Path
run = Path(sys.argv[1])
state = {}
for line in (run / "state.env").read_text().splitlines():
    key, _, value = line.partition("=")
    state[key] = value.strip("'")
def load(name):
    path = run / name
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return None
print("\n==== kvevac Phase 2 run summary ====")
print(f"run dir     {run}")
print(f"instance    {state.get('IID', '-')} in {state.get('AZ', '-')}")
env = load("results/env.json") or {}
print(f"stack       vllm {env.get('vllm', '?')}, torch {env.get('torch', '?')}, "
      f"cuda {env.get('cuda', '?')}, gpu {env.get('gpu', '?')}")
status = (run / "results" / "exit_status")
print(f"job status  {status.read_text().strip() if status.exists() else 'no results'}")
prefill = load("results/prefill.json")
if prefill:
    print(f"prefill     {len(prefill['prefill'])} points, decode "
          f"{prefill['decode_tokens_per_s']} tok/s")
fit = load("results/fit.json")
if fit:
    print("fit         " + ", ".join(f"{k}={v:.4g}" if isinstance(v, float) else f"{k}={v}"
                                      for k, v in fit.items()))
for mode in ("host", "h2d"):
    data = load(f"results/interference-{mode}.json")
    if data:
        rows = ", ".join(f"{r['label']} {r['slowdown']:+.1%}"
                         + (" (load failed)" if r.get("load_failed") else "")
                         for r in data["rows"][1:])
        print(f"slowdown    {mode}: {rows}")
p3 = load("results/phase3.json")
if p3:
    print(f"phase3      tier {p3.get('tier_write_GBps')} GB/s; before flush "
          f"{p3.get('tier_before_flush')}; after {p3.get('tier_after_flush')}")
    print(f"phase3      TTFT speedup {p3.get('ttft_speedup')}; parity {p3.get('output_parity')}")
notice = load("notice.json")
if notice:
    n = notice[0]
    print(f"notice      announced {n['announced_notice_s']}s, rebalance lead "
          f"{n['rebalance_lead_s']}s, last heartbeat vs announced "
          f"{n['termination_vs_announced_s']}s ({n['heartbeats']} heartbeats)")
print(f"FIS         {state.get('EXPERIMENT_STATE', 'not run')}")
try:
    hours = (int(state["ENDED_AT"]) - int(state["LAUNCHED_AT"])) / 3600
    cost = hours * float(state.get("SPOT_PRICE", "0"))
    fis = 0.20 if state.get("EXPERIMENT_ID") else 0.0
    print(f"cost        ~${cost + fis:.2f} ({hours * 60:.0f} instance-min at "
          f"${state.get('SPOT_PRICE')}/h + ~${fis:.2f} FIS; EBS is cents)")
except (KeyError, ValueError):
    pass
PY
  tar -czf "$RUNS/$STAMP.tar.gz" -C "$RUNS" --exclude snapshot.txt --exclude py "$STAMP"
  echo
  say "everything from this run is in $RUNS/$STAMP.tar.gz"
  say "download it (CloudShell: Actions > Download file) and attach it in the project thread"
}

on_exit() {
  local status=$?
  trap '' INT TERM HUP
  if [ "${KEEP:-0}" = 1 ]; then
    say "CloudShell session lost; $IID keeps running (it powers off by itself after $MAX_MIN min)."
    say "Reopen CloudShell and run: bash $0 resume"
    return
  fi
  cleanup_run
  [ -n "${STAMP:-}" ] && summary
  exit "$status"
}

# ---- main -------------------------------------------------------------------------------
cmd="${1:-run}"
case "$cmd" in
  run)
    STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
    RUN_DIR="$RUNS/$STAMP"
    mkdir -p "$RUN_DIR"
    ln -sfn "$STAMP" "$RUNS/latest"
    REGION="${AWS_REGION:-${AWS_DEFAULT_REGION:-$(aws configure get region 2>/dev/null || true)}}"
    REGION="${REGION:-us-east-1}"
    save STAMP "$STAMP"
    save REGION "$REGION"
    ;;
  resume)
    RUN_DIR="$(cd "${2:-$RUNS/latest}" && pwd -P)" || die "no run to resume"
    # shellcheck disable=SC1091
    source "$RUN_DIR/state.env"
    say "resuming run $STAMP (instance ${IID:-none})"
    ;;
  cleanup)
    export AWS_DEFAULT_REGION="${AWS_REGION:-${AWS_DEFAULT_REGION:-us-east-1}}"
    cleanup_all
    exit 0
    ;;
  -h|--help|help) sed -n '2,27p' "$0"; exit 0 ;;
  *) echo "usage: bash $0 [run|resume [run-dir]|cleanup]"; exit 2 ;;
esac
export AWS_DEFAULT_REGION="$REGION" AWS_PAGER=""
install_helpers
trap on_exit EXIT
trap 'KEEP=1; exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM

say "region $REGION; results go to $RUN_DIR"
say "CloudShell ends idle sessions after about 20-30 min without keyboard input. Press a key"
say "now and then; if the session is lost, the instance still powers off after $MAX_MIN min."

[ -n "${IID:-}" ] || launch
if [ "${RESULTS_OK:-0}" != 1 ]; then
  collect_results || true
fi
if [ "$MARKET" != spot ] && [ "${SKIP_FIS:-0}" != 1 ]; then
  say "on-demand instance: skipping the FIS spot interruption (it only works on spot)"
  SKIP_FIS=1
fi
if [ "${SKIP_FIS:-0}" != 1 ] && [ -z "${EXPERIMENT_ID:-}" ] && [ "$(instance_state)" = running ]; then
  interrupt && follow_notice
elif [ -n "${EXPERIMENT_ID:-}" ] && [ -z "${EXPERIMENT_STATE:-}" ]; then
  follow_notice
fi
analyze
